import xml.etree.ElementTree as ET
root = ET.Element("WebsiteConfiguration")

if self.index_document:
    index_doc = ET.SubElement(root, "IndexDocument")
    ET.SubElement(index_doc, "Suffix").text = self.index_document

if self.error_document:
    error_doc = ET.SubElement(root, "ErrorDocument")
    ET.SubElement(error_doc, "Key").text = self.error_document

if self.redirect_all_requests_to:
    redirect = ET.SubElement(root, "RedirectAllRequestsTo")
    ET.SubElement(redirect, "HostName").text = self.redirect_all_requests_to

return ET.tostring(root, encoding='unicode')

