for bucket in storage.buckets:
    total_record_count = 0
    total_storage_size = 0
    total_collection_count = 0

    for collection in bucket.collections:
        total_record_count += len(collection.records)
        total_storage_size += collection.size
        total_collection_count += 1

    if not dry_run:
        bucket.quota.update({
            'record_count': total_record_count,
            'storage_size': total_storage_size,
            'collection_count': total_collection_count
        })

    print(f'Bucket: {bucket.name}, Size: {total_storage_size}, Record Count: {total_record_count}, Collection Count: {total_collection_count}')

