class _ComplementSet:
    def __init__(self, universe):
        self.universe = set(universe)

    def __contains__(self, item):
        return item not in self.universe

    def add(self, item):
        self.universe.discard(item)

    def remove(self, item):
        self.universe.add(item)

    def __repr__(self):
        return f"ComplementSet({self.universe})"

return _ComplementSet(wrapped)

