import re
screen_pattern = re.compile(r"Screen\s+(\w+)\s*:\s*")
device_pattern = re.compile(r"Device\s+(\w+)\s*")

if not next_lines:
    return None

line = next_lines.pop(0)
match = screen_pattern.match(line)
if not match:
    next_lines.insert(0, line)
    return None

screen = {"name": match.group(1), "devices": []}

while next_lines:
    line = next_lines.pop(0)
    match = device_pattern.match(line)
    if not match:
        next_lines.insert(0, line)
        break
    screen["devices"].append(match.group(1))

return Screen(screen["name"], screen["devices"])

