screen_pattern = re.compile(r'^screen\s+(?P<name>\S+)$')
device_pattern = re.compile(r'^device\s+(?P<type>\S+)\s+(?P<name>\S+)$')

line = next_lines.pop(0)
match = screen_pattern.match(line)
if not match:
    next_lines.insert(0, line)
    return None

screen = {'name': match.group('name'), 'devices': []}

while next_lines:
    line = next_lines.pop(0)
    match = device_pattern.match(line)
    if not match:
        next_lines.insert(0, line)
        break

    device = {'type': match.group('type'), 'name': match.group('name')}
    screen['devices'].append(device)

return Screen(screen['name'], screen['devices'])

from typing import List, Optional
import re
screen_pattern = re.compile(r"Screen (\d+) \((\w+)\) (\d+)x(\d+)")
screen = None
if next_lines:
    first_line = next_lines.pop(0)
    match = screen_pattern.match(first_line)
    if match:
        screen = {
            "id": int(match.group(1)),
            "name": match.group(2),
            "width": int(match.group(3)),
            "height": int(match.group(4)),
            "devices": []
        }
        device_pattern = re.compile(r"Device (\d+) \((\w+)\) (\d+)x(\d+)")
        for line in next_lines:
            device_match = device_pattern.match(line)
            if device_match:
                screen["devices"].append({
                    "id": int(device_match.group(1)),
                    "name": device_match.group(2)),
                    "width": int(device_match.group(3)),
                    "height": int(device_match.group(4))
                })
            else:
                break
    else:
        next_lines.insert(0, first_line)
return screen

