# Check if the file or directory exists
if not os.path.exists(filepath):
    print("The file or directory does not exist")
    return

# Check if the path is a file
if os.path.isfile(filepath):
    try:
        os.chmod(filepath, stat.S_IWRITE)  # Change the file to be writable
        os.remove(filepath)  # Remove the file
    except Exception as e:
        print(f"Error: {e}")

# Check if the path is a directory
elif os.path.isdir(filepath):
    try:
        os.chmod(filepath, stat.S_IWRITE)  # Change the directory to be writable
        os.rmdir(filepath)  # Remove the directory
    except Exception as e:
        print(f"Error: {e}")

else:
    print("The path is not a file or directory")

