import re
# Define regular expression pattern for mentions
pattern = r'@\w+'

# Find all mentions in the text
mentions = re.findall(pattern, text)

# If no callback function is provided, use a default function
if format_callback is None:
    def format_callback(mention):
        return '<a href="https://twitter.com/{}">{}</a>'.format(mention[1:], mention)

# Replace each mention in the text with its formatted version
for mention in mentions:
    text = text.replace(mention, format_callback(mention))

return text

