import ssl
if not ssl_context:
    ssl_context = ssl.create_default_context()

if not self.has_capability('STARTTLS'):
    raise Exception("The server does not support STARTTLS")

try:
    typ, data = self._simple_command('STARTTLS')
    if typ != 'OK':
        raise Exception("Could not start TLS: %s" % data)
    self.sock = ssl_context.wrap_socket(self.sock, server_hostname=self.host)
    self.file = self.sock.makefile('rb')
    self.get_response()
except Exception as e:
    raise Exception("Could not establish SSL connection: %s" % str(e))

return "STARTTLS command executed successfully"

