    r'narrow/stream/(\d+-)?(.*)/near/(\d+)',
    r'narrow/stream/(\d+-)?(.*)/topic/(.*)',
    r'narrow/stream/(\d+-)?(.*)/topic/(.*)/near/(\d+)',
]

for format in formats:
    match = re.match(format, link)
    if match:
        groups = match.groups()
        if len(groups) == 2:
            parsed_link = {'stream_name': unquote(groups[1])}
        elif len(groups) == 3:
            parsed_link = {'stream_name': unquote(groups[1]), 'message_id': groups[2]}
        elif len(groups) == 4:
            parsed_link = {'stream_name': unquote(groups[1]), 'topic_name': unquote(groups[2])}
        elif len(groups) == 5:
            parsed_link = {'stream_name': unquote(groups[1]), 'topic_name': unquote(groups[2]), 'message_id': groups[4]}
        break

return parsed_link

