parsed_link = {}
match = re.match(r'narrow/stream/(\d+-)?(.+)', link)
if match:
    parsed_link['stream_name'] = match.group(2)
    if 'near' in link:
        match = re.match(r'narrow/stream/(\d+-)?(.+)/near/(\d+)', link)
        if match:
