        if match:
            parsed_link['topic_name'] = match.group(3)
            parsed_link['message_id'] = match.group(4)
        else:
            match = re.match(r'narrow/stream/(\d+-)?(.+)/topic/(.+)', link)
            if match:
                parsed_link['topic_name'] = match.group(3)
return parsed_link

