import pickle
import pandas as pd
assert batch_dim == 0, "PandasDataFrameContainer only supports batch_dim of 0."

if isinstance(batch, pd.Series):
    batch = batch.to_frame()

meta = {"format": "pickle5"}

buffer_bs = []
indices = []

for column in batch.columns:
    series = batch[column]
    if isinstance(series.dtype, pd.CategoricalDtype):
        indices.append(column)
        buffer_bs.append(series.cat.codes.to_numpy())
    else:
        buffer_bs.append(series.to_numpy())

if indices:
    meta["with_buffer"] = True
    meta["indices"] = indices
    concat_buffer_bs = np.concatenate(buffer_bs)
    bs = base64.b64encode(pickle.dumps(concat_buffer_bs)).decode()
    meta["buffer_bs"] = bs
else:
    meta["with_buffer"] = False
    bs = base64.b64encode(pickle.dumps(batch)).decode()

data = {"data": bs}
batch_shape = batch.shape

return Payload(data, batch_shape, meta)

