import requests
import threading

errors = []

def download_url(url):
    nonlocal counter
    try:
        response = requests.get(url, timeout=config.get('timeout', 5))
        response.raise_for_status()
        counter += 1
    except Exception as e:
        errors.append((url, str(e)))

while url_store:
    url = url_store.pop(0)
    if config.get('multithreaded', False):
        threading.Thread(target=download_url, args=(url,)).start()
    else:
        download_url(url)

return errors, counter

