from configparser import ConfigParser
import pathlib
import os

xdg_dirs = {
    "XDG_CACHE_HOME": pathlib.Path("~/.cache").expanduser(),
    "XDG_CONFIG_HOME": pathlib.Path("~/.config").expanduser(),
    "XDG_DATA_HOME": pathlib.Path("~/.local/share").expanduser(),
    "XDG_RUNTIME_DIR": pathlib.Path("/run/user/{}".format(os.getuid())),
    "XDG_CONFIG_DIRS": [pathlib.Path("/etc/xdg")],
    "XDG_DATA_DIRS": [pathlib.Path("/usr/local/share"), pathlib.Path("/usr/share")],
}

for key, default in xdg_dirs.items():
    value = os.environ.get(key)
    if value:
        if isinstance(default, list):
            xdg_dirs[key] = [pathlib.Path(path).expanduser() for path in value.split(":")]
        else:
            xdg_dirs[key] = pathlib.Path(value).expanduser()

user_dirs_file = xdg_dirs["XDG_CONFIG_HOME"] / "user-dirs.dirs"
if user_dirs_file.exists():
    config = ConfigParser()
    with user_dirs_file.open() as f:
        config.read_file(f)
    if "XDG user dirs" in config:
        for key, value in config["XDG user dirs"].items():
            xdg_dirs[key] = pathlib.Path(value).expanduser()

return xdg_dirs

