import os
import json

formatted_config = []

for extension in extensions_data:
    # Read the default configuration file
    with open(os.path.join('configs', extension['name'], 'default.json')) as f:
        default_config = json.load(f)

    # Load the raw configuration
    raw_config = extension['config']

    # Validate the configuration against the schema
    try:
        validate(instance=raw_config, schema=default_config['schema'])
    except ValidationError as e:
        raise ValueError(f"Invalid configuration for extension {extension['name']}: {str(e)}")

    # Create a header with version information
    header = {
        'name': extension['name'],
        'version': default_config['version'],
    }

    # Format the configuration
    formatted_config.append({
        'header': header,
        'config': raw_config,
    })

return json.dumps(formatted_config)

