# Let's assume we have a dictionary with all the tunings
all_tunings = {
    "guitar": {"6": ["EADGBE", "DADGAD", "CGCGCE"], "7": ["BEADGBE", "AEADGBE"]},
    "bass": {"4": ["EADG"], "5": ["BEADG"], "6": ["BEADGC"]},
    "ukulele": {"4": ["GCEA", "ADF#B"]},
    "mandolin": {"4": ["GDAE"], "8": ["GGDDAAEE"]}
}

# Initialize an empty list to store the matching tunings
matching_tunings = []

# If an instrument is specified, search for tunings of that instrument
if instrument:
    instrument = instrument.lower()  # Make case-insensitive
    if instrument in all_tunings:
        # If a number of strings is specified, search for tunings with that number of strings
        if nr_of_strings:
            nr_of_strings = str(nr_of_strings)  # Convert to string to match dictionary keys
            if nr_of_strings in all_tunings[instrument]:
                matching_tunings.extend(all_tunings[instrument][nr_of_strings])
        else:
            # If no number of strings is specified, return all tunings for the instrument
            for tunings in all_tunings[instrument].values():
                matching_tunings.extend(tunings)

# If no instrument is specified, search for tunings based on the number of strings
elif nr_of_strings:
    nr_of_strings = str(nr_of_strings)  # Convert to string to match dictionary keys
    for instrument_tunings in all_tunings.values():
        if nr_of_strings in instrument_tunings:
            matching_tunings.extend(instrument_tunings[nr_of_strings])

# If no instrument or number of strings is specified, return all tunings
else:
    for instrument_tunings in all_tunings.values():
        for tunings in instrument_tunings.values():
            matching_tunings.extend(tunings)

return matching_tunings

