import json
import re
if counters is None:
    counters = {}

statuses = []
other = []

if isinstance(stderr, bytes):
    stderr = stderr.decode().split('\n')
elif hasattr(stderr, 'readlines'):
    stderr = stderr.readlines()

counter_re = re.compile(r'^Counters: (.+)$')
status_re = re.compile(r'^Status: (.+)$')

for line in stderr:
    line = line.strip()
    if not line:
        continue

    counter_match = counter_re.match(line)
    if counter_match:
        new_counters = json.loads(counter_match.group(1))
        for group, group_counters in new_counters.items():
            if group not in counters:
                counters[group] = {}
            for counter, count in group_counters.items():
                counters[group][counter] = counters[group].get(counter, 0) + count
        continue

    status_match = status_re.match(line)
    if status_match:
        statuses.append(status_match.group(1))
        continue

    other.append(line)

return {'counters': counters, 'statuses': statuses, 'other': other}

