for path in glob.glob(path_glob):
    if os.path.isdir(path):
        # If the path is a directory, recursively walk through all the subdirectories
        for root, dirs, files in os.walk(path):
            for file in files:
                # Yield the file paths in file URI format
                yield 'file://' + os.path.join(root, file)
