for session in self.sessions:
    if use_start_end_tokens:
        session = ['<start>'] + session + ['<end>']
    session_length = len(session)
    likelihoods = self.compute_likelihoods(session)
    geometric_mean_likelihood = np.prod(likelihoods) ** (1.0 / session_length)
    session['geometric_mean_likelihood'] = geometric_mean_likelihood

    for window_length in [2, 3]:
