import stringprep

# Normalize the input string to NFKC form
s = unicodedata.normalize('NFKC', s)

# Apply the SASLprep profile
out = []
for c in s:
    # Map non-ASCII space characters to space
    if stringprep.in_table_c11(c):
        out.append(' ')
    # Map commonly mapped to nothing characters to nothing
    elif stringprep.in_table_b1(c):
        continue
    # Check for prohibited output
    elif (stringprep.in_table_c12(c) or stringprep.in_table_c21(c) or
          stringprep.in_table_c22(c) or stringprep.in_table_c3(c) or
          stringprep.in_table_c4(c) or stringprep.in_table_c5(c) or
          stringprep.in_table_c6(c) or stringprep.in_table_c7(c) or
          stringprep.in_table_c8(c) or stringprep.in_table_c9(c)):
        raise ValueError('Prohibited character: %r' % c)
    else:
        out.append(c)

# Check for bidirectional strings
if stringprep.in_table_d1(s):
    if not stringprep.in_table_d1(out[0]) or not stringprep.in_table_d1(out[-1]):
        raise ValueError('Bidirectional strings must start and end with a character of class R or AL')
elif stringprep.in_table_d2(s):
    if stringprep.in_table_d1(out):
        raise ValueError('If a string contains any character of class R or AL, no character of class EN may be present')

return ''.join(out)

