# Calculate the check digit using Luhn algorithm
digits = [int(d) for d in number]
for i in range(len(digits) - 2, -1, -2):
    digits[i] *= 2
    if digits[i] > 9:
        digits[i] -= 9
check_digit = (10 - sum(digits) % 10) % 10

return number + str(check_digit)

