import re

# Regular expression pattern for a fingerprint
# A fingerprint is typically a string of alphanumeric characters
pattern = r'\b[0-9a-f]{5,40}\b'
match = re.search(pattern, path)

if match:
    # If a fingerprint is found, remove it from the file path
    path = re.sub(pattern, '', path)
    return (path, True)
else:
    # If no fingerprint is found, return the original file path
    return (path, False)

