def toc_hook(state, startLine, endLine, silent):
    """
    This function hooks into the markdown parser and extracts the table of contents.
    """
    # Check if the markdown instance has a toc attribute
    if not hasattr(md, 'toc'):
        md.toc = []

    # Extract the TOC items
    for i in range(startLine, endLine):
        line = state.src[i]
        if line.startswith('#'):
            level = len(line) - len(line.lstrip('#'))
            if min_level <= level <= max_level:
                title = line.lstrip('#').strip()
                if heading_id:
                    id = heading_id(title)
                else:
                    id = title.lower().replace(' ', '-')
                md.toc.append((level, title, id))
    return False

