import logging
import time
from pymongo.errors import AutoReconnect, OperationFailure
def wrapper(*args, **kwargs):
    _retry_count = 0
    _in_retry = False
    while True:
        try:
            return f(*args, **kwargs)
        except (AutoReconnect, OperationFailure) as e:
            if 'arctic' in str(e):
                logging.error(f"Error in function {f.__name__}: {str(e)}")
            if _retry_count >= 3:  # max retries
                raise
            _retry_count += 1
            _in_retry = True
            time.sleep(0.1)  # wait before retrying
        finally:
            _in_retry = False
return wrapper

