import os
import requests
if input_source.startswith("https://tenor.com/view/"):
    gif_id = input_source.split("/")[-1]
    gif_url = f"https://media.tenor.com/images/{gif_id}/tenor.gif"
else:
    if os.path.isfile(input_source):
        # if the input source is a local file path, upload the file to Tenor and get the GIF URL
        with open(input_source, 'rb') as file:
            upload_response = requests.post(
                "https://api.tenor.com/v1/upload",
                headers={"Content-Type": "application/octet-stream", "Key": api_key},
                data=file.read()
            )
            gif_url = upload_response.json()["results"][0]["url"]
    else:
        # if the input source is a search query, send a request to the Tenor GIF API to get the GIF URL
        search_response = requests.get(
            "https://api.tenor.com/v1/search",
            params={"q": input_source, "key": api_key, "limit": 1}
        )
        gif_url = search_response.json()["results"][0]["url"]

return gif_url

