def _parse_record(json_record):
    # This function is a helper function that takes a JSON record and converts it into a Record object.
    # If the JSON record is invalid, it returns None.
    try:
        return Record(json_record)
    except:
        return None

# Use a list comprehension to parse each JSON record and filter out any None values.
parsed_records = [record for record in (_parse_record(json_record) for json_record in json_records) if record is not None]

return parsed_records

