lines = text.split('\n')
for i in range(len(lines)):
    j = 0
    while j < len(lines[i]):
        if lines[i][j] == '\b':
            if j > 0:
                lines[i] = lines[i][:j-1] + lines[i][j+1:]
                j -= 1
            else:
                lines[i] = lines[i][j+1:]
        else:
            j += 1
return '\n'.join(lines)

